insert into public.content_collections (slug,title,description,collection_type,access_policy,status,sort_priority,metadata)
values ('progress-without-noise','Progress Without Noise','Guias MyTrainX para interpretar peso, medidas, composição corporal estimada, fotos e performance com contexto.','knowledge_pack','public','published',95,jsonb_build_object('launch','2026-09-26','surface','library_and_progress'))
on conflict (slug) do update set title=excluded.title,description=excluded.description,access_policy=excluded.access_policy,status='published',sort_priority=excluded.sort_priority,metadata=public.content_collections.metadata||excluded.metadata,updated_at=now();

insert into public.content_collection_items (collection_id,content_id,position,section_title,is_required,metadata)
select cc.id,ci.id,row_number() over(order by ci.featured desc,ci.title)::int,'Progress Without Noise',false,'{}'::jsonb
from public.content_collections cc join public.content_items ci on ci.metadata->>'collection'='progress-without-noise'
where cc.slug='progress-without-noise'
on conflict (collection_id,content_id) do update set section_title=excluded.section_title;

with ebook_doc as (
 select kd.id from public.knowledge_documents kd join public.content_items ci on ci.id=kd.content_id
 where ci.slug='progress-sem-ruido-v1' and kd.version=1 limit 1
), seed as (
 select * from jsonb_to_recordset('[{"heading":"Progresso é um sistema, não um número","body":"A evolução física deve ser interpretada com múltiplas dimensões: consistência de treino, performance, medidas corporais quando relevantes, recuperação e experiência do utilizador. Peso não é composição corporal; composição corporal não é performance; uma fotografia não quantifica gordura ou músculo. A melhor leitura aparece na combinação de indicadores escolhidos de acordo com o objetivo da pessoa."},{"heading":"O que a balança mede","body":"Uma balança comum mede massa corporal naquele instante. Água, glicogênio, conteúdo gastrointestinal, ingestão recente, horário e outras condições podem alterar o número sem representar mudança equivalente de gordura. Leituras isoladas devem ser tratadas como pontos numa série, e não como veredictos sobre progresso."},{"heading":"Como pesar-se de forma consistente","body":"Para melhorar comparabilidade, use a mesma balança em superfície estável, condições semelhantes de horário e roupa e registre o contexto quando a rotina estiver muito diferente. A frequência não precisa ser diária. Se pesar-se frequentemente aumentar ansiedade ou comportamento compulsivo, reduzir a frequência ou deixar de usar a balança é uma escolha válida."},{"heading":"Circunferências corporais","body":"Circunferências podem complementar peso, desde que o protocolo seja repetível. Para cintura, o protocolo da OMS usa o ponto médio entre a última costela palpável e a crista ilíaca, com fita horizontal, ajustada sem comprimir a pele e leitura ao final de uma expiração normal. Outros pontos anatômicos também precisam de técnica consistente registrada."},{"heading":"BIA e smart scales","body":"Bioimpedância mede propriedades elétricas e usa algoritmos para estimar compartimentos corporais. Valores como percentual de gordura e massa muscular não são medições diretas. Revisões recentes mostram limitações na concordância individual contra métodos de referência. A utilidade prática aumenta quando o mesmo dispositivo é usado em condições semelhantes e o resultado é tratado como tendência estimada."},{"heading":"Massa muscular estimada","body":"MyTrainX pode armazenar estimativas de massa muscular vindas de smart scales, BIA profissional, DXA e outras fontes, preservando método e dispositivo. O sistema não deve afirmar ganho ou perda precisa de músculo apenas pela diferença entre duas leituras de BIA. A interpretação deve combinar tendência, força, medidas e contexto."},{"heading":"Fotos de evolução","body":"Fotos são documentação visual, não exame de composição corporal. Para comparações mais úteis, padronize local, distância, altura da câmera, iluminação, roupa e postura. Frente, lado e costas são suficientes para um set básico. Frequência semanal, quinzenal ou mensal pode ser escolhida conforme a utilidade e o conforto do utilizador."},{"heading":"Privacidade de fotos","body":"Fotos de progresso devem ser privadas por padrão. No MyTrainX elas são destinadas a Storage privado, acesso autenticado e URLs temporárias. Não são automaticamente enviadas ao Coach X ou usadas em análise de IA. Qualquer análise visual futura exige consentimento explícito e permanece não diagnóstica."},{"heading":"IA e composição corporal","body":"Modelos de visão e aplicações podem estimar características corporais em protocolos específicos, mas uma fotografia casual não justifica apresentar um percentual de gordura ou massa muscular como medição precisa. O MyTrainX deve evitar falsa precisão e usar IA, quando autorizada, para observações descritivas e contexto, não diagnóstico."},{"heading":"Performance como progresso","body":"A balança pode ficar estável enquanto a pessoa melhora repetições, carga, técnica, amplitude, capacidade de trabalho e consistência. Para objetivos de performance, essas métricas podem ser mais relevantes do que peso. O sistema deve permitir que o utilizador escolha quais indicadores representam o seu objetivo."},{"heading":"Check-in semanal","body":"Energia, sono, soreness, stress, motivação, consistência alimentar e sessões planejadas/concluídas adicionam contexto aos dados objetivos. Um único check-in ruim não determina mudança automática. Padrões repetidos ao longo de semanas podem justificar conversa e ajuste prudente com Coach X."},{"heading":"Como interpretar um platô","body":"Antes de chamar uma situação de platô, verifique duração, qualidade da medição, consistência do treino, recuperação, objetivo atual e possíveis progressos em outras dimensões. Uma semana costuma ser pouca informação para redefinir um plano. Prefira ajustes pequenos, testáveis e reversíveis."},{"heading":"Protocolo de quatro semanas","body":"Semana 1 estabelece baseline com poucas métricas úteis. Semana 2 testa se o protocolo é repetível. Semana 3 adiciona contexto de treino e recuperação. Semana 4 revisa o conjunto: objetivo, qualidade dos dados, mudanças observadas, provável ruído, menor ajuste necessário e elementos que devem permanecer iguais."}]'::jsonb) as x(heading text,body text)
), numbered as (
 select heading,body,row_number() over() - 1 as ordinal from seed
)
insert into public.knowledge_chunks (document_id,ordinal,heading,body,token_count,locator,metadata)
select ebook_doc.id,numbered.ordinal,numbered.heading,numbered.body,greatest(1,round(length(numbered.body)/4.0)::int),
jsonb_build_object('chapter',numbered.ordinal+1),jsonb_build_object('review_gate','scientific','source','PROGRESS-SEM-RUIDO-V1.md')
from ebook_doc,numbered
on conflict (document_id,ordinal) do update set heading=excluded.heading,body=excluded.body,token_count=excluded.token_count,locator=excluded.locator,metadata=excluded.metadata;

update public.knowledge_documents kd set status='ready',extraction_method='manual_editorial_chunking_v1',
char_count=(select sum(length(kc.body)) from public.knowledge_chunks kc where kc.document_id=kd.id),
token_estimate=(select sum(coalesce(kc.token_count,0)) from public.knowledge_chunks kc where kc.document_id=kd.id),
metadata=kd.metadata||jsonb_build_object('chunks_ready',true,'retrieval_blocked_until_review',true),updated_at=now()
from public.content_items ci where kd.content_id=ci.id and ci.slug='progress-sem-ruido-v1' and kd.version=1;
